/* Election Atlas: local CEC data, D3 geometry/zoom, no runtime API dependency. */
'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const COLORS={'民進黨':'#149c79','國民黨':'#477bdb','民眾黨':'#28b7c0','無黨籍':'#ad8d65','親民黨':'#e89945'};
const color=p=>COLORS[p]||'#9983b4',fmt=n=>Number(n||0).toLocaleString('en-US'),pct=n=>n==null?'—':Number(n).toFixed(2)+'%',sign=n=>(n>0?'+':'')+n.toFixed(2);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const CFG={president:{year:2024,title:'總統副總統',date:'01.13',pres:true},legislator:{year:2024,title:'區域立法委員',date:'01.13'}};
let data,topology,counties,towns,records,geoByKey={},mapSvg,world,zoom,transform=d3.zoomIdentity,w=0,h=0,resizeTimer,toastTimer;
const state={e:'president',metric:'winner',level:'town',chart:'map',county:'',key:'',candidate:'賴清德',swingParty:'民進黨',labels:true,sort:'margin',brushed:[],brushEnabled:false,distribution:'swarm',pins:[],drawer:null};
const duration=()=>matchMedia('(prefers-reduced-motion:reduce)').matches?0:550;
function isLeg(){return state.e==='legislator'}
function rec(key=state.key){return records[key||'00000/000']}
function valid(r){return r&&data.counties[r.county]&&r.total>0}
function areaName(r,full=false){if(!r)return '全臺';const c=data.counties[r.county]||'全臺';if(isLeg())return c+' · 第'+Number(r.district)+'選區';return r.town==='000'?c:(full?c+' · ':'')+r.name}
function keyOf(r){return r.county+(isLeg()?':'+r.district:'')+'/'+r.town}
