 if(!$('#candidate-filter').hidden){const opts=state.metric==='swing'?['民進黨','國民黨']:data[state.e]['00000/000'].candidates.map(c=>c.name);$('#candidate-filter-label').textContent=state.metric==='swing'?'政黨':'候選人';$('#candidate-select').innerHTML=opts.map(n=>'<option>'+esc(n)+'</option>').join('');$('#candidate-select').value=state.metric==='swing'?state.swingParty:state.candidate}
 $('#map').toggleAttribute('hidden',state.chart!=='map');$('#scatter').toggleAttribute('hidden',state.chart==='map');$('.map-controls').hidden=state.chart!=='map';$('.zoom-readout').hidden=state.chart!=='map';$('.map-metrics').hidden=['scatter','ternary','small'].includes(state.chart);$('#brush-toggle').hidden=state.chart!=='ternary';$('#brush-toggle').classList.toggle('active',state.brushEnabled);$('#clear-brush').hidden=!state.brushed.length;$('#clear-brush').textContent='已框選 '+state.brushed.length+' 地區 ×';$('#small-view-tab').textContent=isLeg()?'議席':'並列';$('#candidate-filter').hidden=['scatter','ternary','small'].includes(state.chart)||$('#candidate-filter').hidden;
